css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .texto-box{border: 2px solid var(--bosque); border-radius: 12px; padding: 10px 12px; margin-bottom: 10px;}
.mz .texto-parrafo{font-size: 16px; font-weight: 600; line-height: 1.55;}
.mz .significados-lista{display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px;}
.mz .significado-item{display: flex; flex-direction: column; gap: 3px;}
.mz .significado-palabra{font-size: 15px; font-weight: 700;}
.mz .opciones-lista{display: flex; flex-direction: column; gap: 3px; padding-left: 14px;}
.mz .opcion-item{display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 600;}
.mz .opcion-circulo{width: 18px; height: 18px; border: 1.5px solid var(--bosque); border-radius: 50%; flex-shrink: 0;}
.mz .banco{font-family: sans-serif; font-size: 12px; font-weight: 700; background: #f0f0f0; border: 1px solid #ccc; border-radius: 6px; padding: 4px 10px; display: inline-block; margin-bottom: 7px;}
.mz .completar-lista{display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px;}
.mz .completar-frase{font-size: 15px; font-weight: 600; line-height: 1.5;}
.mz .hueco{display: inline-block; border-bottom: 1.5px solid var(--bosque); min-width: 100px; vertical-align: bottom;}
.mz .emparejar-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 6px 20px; margin-bottom: 10px;}
.mz .emparejar-col{display: flex; flex-direction: column; gap: 9px;}
.mz .emparejar-item{display: flex; align-items: center; gap: 8px;}
.mz .emparejar-caja{width: 24px; height: 24px; border: 1.5px solid var(--bosque); border-radius: 4px; flex-shrink: 0;}
.mz .emparejar-palabra{font-size: 15px; font-weight: 700;}
.mz .def-item{display: flex; align-items: flex-start; gap: 7px;}
.mz .def-letra{font-family: sans-serif; font-size: 11px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 50%; width: 20px; height: 20px; display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 1px;}
.mz .def-texto{font-size: 14px; font-weight: 600; line-height: 1.3;}
.mz .escribir-lineas{display: flex; flex-direction: column; gap: 6px; margin-bottom: 8px;}
.mz .escribir-linea{border-bottom: 1.5px solid var(--bosque); height: 22px; width: 100%;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
.mz .completar-frase,.mz .def-texto,.mz .texto-parrafo{line-height: 1.725 !important;}
